/* prog39_horner.c
 * Reimplementation of the original binary's observable behaviour.
 *
 * Usage:
 *   ./prog39_horner X C0 C1 ... Cn
 *
 *   X  – integer, -10 <= X <= 10 (evaluation point)
 *   Ci – integer coefficients, highest degree first (max 12 coefficients)
 *
 * Output:
 *   NO_INPUT      – if X is missing
 *   OUT_OF_RANGE  – if |X| > 10 or more than 12 coefficients are given
 *   BAD_INPUT     – if any argument is not a pure decimal integer
 *   EMPTY         – if the call contains only X (no coefficients)
 *   <value>       – the polynomial value (signed 64‑bit) otherwise
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_COEFF 12

/* Strict decimal integer parsing: no extra characters, no overflow. */
static int parse_int(const char *s, long long *out)
{
    char *end;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno != 0)               return 0;   /* overflow / underflow */
    if (end == s)                 return 0;   /* no digits */
    if (*end != '\0')            return 0;   /* extra characters */
    *out = v;
    return 1;
}

int main(int argc, char *argv[])
{
    /* No argument for x */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Too many arguments (program name + x + >12 coefficients) */
    if (argc > 14) {                 /* 1 (program) + 1 (x) + 12 coeffs */
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long x;
    if (!parse_int(argv[1], &x)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (x < -10 || x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    int coeff_cnt = argc - 2;        /* number of coefficients supplied */
    if (coeff_cnt == 0) {
        puts("EMPTY");
        return 0;
    }

    long long coeff[MAX_COEFF];
    for (int i = 0; i < coeff_cnt; ++i) {
        if (!parse_int(argv[2 + i], &coeff[i])) {
            puts("BAD_INPUT");
            return 0;
        }
    }

    /* Horner evaluation */
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    return 0;
}
